const queryClient = new QueryClient();

const nav = [
  { href: '/', label: 'Control room', icon: LayoutDashboard },
  { href: '/tasks', label: 'Task register', icon: ClipboardCheck },
  { href: '/aircraft', label: 'Fleet', icon: Plane },
  { href: '/records', label: 'Records', icon: FileCheck2 },
];

const pretty = (value?: string | null) => value ? value.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase()) : '—';
const date = (value?: string | null) => value ? new Intl.DateTimeFormat('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }).format(new Date(value)) : '—';
const relative = (value?: string | null) => value ? new Intl.RelativeTimeFormat('en', { numeric: 'auto' }).format(Math.round((new Date(value).getTime() - Date.now()) / 86400000), 'day') : '—';
const number = (value?: number | null) => value == null ? '—' : value.toLocaleString('en-GB');

