function PageIntro({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><div className="amp-eyebrow mb-2 text-primary">{eyebrow}</div><h1 className="text-[27px] font-extrabold tracking-[-.055em] text-foreground md:text-[32px]">{title}</h1><p className="mt-2 max-w-2xl text-[13px] leading-relaxed text-muted-foreground">{description}</p></div>{action}</div>;
}
function Button({ children, onClick, variant = 'primary', type = 'button', disabled = false, testId = 'button-action' }: { children: ReactNode; onClick?: () => void; variant?: 'primary' | 'secondary' | 'quiet' | 'danger'; type?: 'button' | 'submit'; disabled?: boolean; testId?: string }) {
  const cls = variant === 'primary' ? 'bg-primary text-primary-foreground hover:brightness-110' : variant === 'danger' ? 'border border-destructive/30 bg-destructive/10 text-destructive hover:bg-destructive/15' : variant === 'secondary' ? 'border border-border bg-card text-foreground hover:bg-muted' : 'text-muted-foreground hover:bg-muted hover:text-foreground';
  return <button type={type} onClick={onClick} disabled={disabled} data-testid={testId} className={`inline-flex items-center justify-center gap-2 rounded-sm px-3.5 py-2.5 text-[12px] font-bold transition-all active:translate-y-px disabled:cursor-not-allowed disabled:opacity-50 ${cls}`}>{children}</button>;
}
function Status({ value }: { value: string }) {
  const danger = ['overdue', 'grounded', 'rejected'].includes(value);
  const warn = ['due_soon', 'attention', 'pending'].includes(value);
  const success = ['on_track', 'serviceable', 'reviewed', 'completed'].includes(value);
  return <span data-testid={`status-${value}`} className={`inline-flex items-center gap-1.5 rounded-full border px-2 py-1 text-[10px] font-bold uppercase tracking-[.04em] ${danger ? 'border-red-200 bg-red-50 text-[#ad3933]' : warn ? 'border-amber-200 bg-amber-50 text-[#9a6700]' : success ? 'border-emerald-200 bg-emerald-50 text-[#2c7853]' : 'border-border bg-muted text-muted-foreground'}`}><span className={`h-1.5 w-1.5 rounded-full ${danger ? 'bg-[#c9473d]' : warn ? 'bg-[#d79d1d]' : success ? 'bg-[#3c9d6c]' : 'bg-muted-foreground'}`} />{pretty(value)}</span>;
}
function LoadingRows({ count = 4 }: { count?: number }) { return <div className="space-y-2">{Array.from({ length: count }).map((_, i) => <div key={i} className="h-14 animate-pulse rounded-sm bg-muted" />)}</div>; }
function ErrorState({ retry }: { retry: () => void }) { return <div className="amp-panel flex flex-col items-center justify-center p-12 text-center"><AlertTriangle size={24} className="mb-3 text-[#c9473d]" /><div className="text-sm font-bold">Operational data unavailable</div><p className="mt-1 text-xs text-muted-foreground">The feed did not respond. Try again before making a release decision.</p><Button variant="secondary" onClick={retry} testId="button-retry"><RefreshCw size={13} /> Retry feed</Button></div>; }
function EmptyState({ icon: Icon = Inbox, title, detail, action }: { icon?: typeof Inbox; title: string; detail: string; action?: ReactNode }) { return <div className="amp-panel flex flex-col items-center justify-center p-12 text-center"><div className="mb-3 flex h-11 w-11 items-center justify-center rounded-full bg-muted text-primary"><Icon size={20} /></div><div className="text-sm font-bold">{title}</div><p className="mt-1 max-w-sm text-xs leading-relaxed text-muted-foreground">{detail}</p>{action && <div className="mt-4">{action}</div>}</div>; }
function Metric({ label, value, detail, icon: Icon, tone = 'blue' }: { label: string; value: string | number; detail: string; icon: typeof Gauge; tone?: 'blue' | 'amber' | 'red' | 'green' }) {
  const color = tone === 'amber' ? 'text-[#9a6700] bg-amber-50' : tone === 'red' ? 'text-[#ad3933] bg-red-50' : tone === 'green' ? 'text-[#2c7853] bg-emerald-50' : 'text-primary bg-[#e7f0f4]';
  return <div className="amp-panel amp-rise rounded-sm p-4"><div className="flex items-start justify-between"><div className="amp-eyebrow text-muted-foreground">{label}</div><div className={`flex h-7 w-7 items-center justify-center rounded-sm ${color}`}><Icon size={14} /></div></div><div data-testid={`metric-${label.toLowerCase().replaceAll(' ', '-')}`} className="amp-mono mt-3 text-[26px] font-medium tracking-[-.07em]">{value}</div><div className="mt-1 text-[11px] text-muted-foreground">{detail}</div></div>;
}

function Dashboard() {
  const qc = useQueryClient();
  const summary = useGetDashboardSummary();
  const activity = useGetActivity({ limit: 8 });
  const aircraft = useListAircraft();
  const tasks = useListMaintenanceTasks();
  const records = useListMaintenanceRecords({ reviewStatus: 'pending' });
  const urgent = useMemo(() => (tasks.data ?? []).filter((t) => t.status === 'overdue' || t.status === 'due_soon').slice(0, 5), [tasks.data]);
  if (summary.isLoading || aircraft.isLoading || tasks.isLoading) return <><PageIntro eyebrow="Flight operations / live" title="Good afternoon, control team." description="Loading the current maintenance picture across the Northstar fleet." /><LoadingRows count={6} /></>;
  if (summary.isError) return <ErrorState retry={() => summary.refetch()} />;
  const s = summary.data;
  return <div className="amp-fade">
    <PageIntro eyebrow="Flight operations / live" title="Good afternoon, control team." description="The fleet is being watched. Here is the maintenance picture as of 12:42 UTC." action={<Button onClick={() => { summary.refetch(); tasks.refetch(); aircraft.refetch(); qc.invalidateQueries({ queryKey: getGetActivityQueryKey({ limit: 8 }) }); }} variant="secondary" testId="button-refresh-dashboard"><RefreshCw size={13} /> Refresh snapshot</Button>} />
    <div className="mb-7 grid gap-3 sm:grid-cols-2 xl:grid-cols-5">
      <Metric label="Fleet" value={number(s?.aircraftCount)} detail="aircraft under control" icon={Plane} tone="blue" />
      <Metric label="Overdue" value={number(s?.overdueCount)} detail="requires immediate action" icon={AlertTriangle} tone="red" />
      <Metric label="Due soon" value={number(s?.dueSoonCount)} detail="within the next 30 days" icon={Clock3} tone="amber" />
      <Metric label="Open tasks" value={number(s?.openTaskCount)} detail="across all intervals" icon={ClipboardCheck} tone="blue" />
      <Metric label="Flight hours" value={number(s?.utilisationHours)} detail="fleet total utilisation" icon={BarChart3} tone="green" />
    </div>
    <div className="grid gap-5 xl:grid-cols-[1.35fr_1fr]">
      <section className="amp-panel amp-grid overflow-hidden rounded-sm"><div className="flex items-center justify-between border-b border-border bg-card/90 px-5 py-4"><div><div className="amp-eyebrow text-primary">Attention required</div><h2 className="mt-1 text-[15px] font-extrabold">Urgent due items</h2></div><Link href="/tasks" data-testid="link-view-all-tasks" className="flex items-center gap-1 text-[11px] font-bold text-primary hover:underline">Open register <ArrowUpRight size={13} /></Link></div>{urgent.length === 0 ? <div className="p-6"><EmptyState icon={CheckCircle2} title="No urgent items" detail="The active due horizon is clear." /></div> : <div className="divide-y divide-border/70 bg-card/75">{urgent.map((task, i) => <div key={task.id} data-testid={`row-urgent-task-${task.id}`} className={`group grid gap-3 px-5 py-4 transition-colors hover:bg-muted/50 sm:grid-cols-[1fr_auto] ${i === 0 ? 'border-l-2 border-l-[#c9473d]' : ''}`}><div className="min-w-0"><div className="mb-1 flex flex-wrap items-center gap-2"><span className="amp-mono text-[10px] text-muted-foreground">{task.taskNumber}</span><Status value={task.status} /></div><div className="truncate text-[13px] font-bold">{task.title}</div><div className="mt-1 flex flex-wrap gap-3 text-[11px] text-muted-foreground"><span className="font-semibold text-primary">{task.aircraftRegistration}</span><span>{pretty(task.category)}</span><span>Owner: {task.owner}</span></div></div><div className="flex items-center justify-between gap-5 sm:block sm:text-right"><div className={`amp-mono text-[12px] font-medium ${task.status === 'overdue' ? 'text-[#ad3933]' : 'text-[#9a6700]'}`}>{task.status === 'overdue' ? 'Past due' : `Due ${date(task.nextDueAt)}`}</div><Link href="/tasks" data-testid={`link-task-detail-${task.id}`} className="mt-1 inline-flex items-center gap-1 text-[10px] font-bold text-muted-foreground opacity-70 hover:text-primary group-hover:opacity-100">Review <ChevronRight size={12} /></Link></div></div>)}</div>}</section>
      <section className="amp-panel rounded-sm"><div className="flex items-center justify-between border-b border-border px-5 py-4"><div><div className="amp-eyebrow text-primary">Fleet pulse</div><h2 className="mt-1 text-[15px] font-extrabold">Aircraft snapshot</h2></div><Link href="/aircraft" data-testid="link-view-fleet" className="text-muted-foreground hover:text-primary"><ArrowUpRight size={15} /></Link></div><div className="p-5">{aircraft.isError ? <ErrorState retry={() => aircraft.refetch()} /> : (aircraft.data ?? []).slice(0, 5).map((a) => <div key={a.id} data-testid={`row-aircraft-snapshot-${a.id}`} className="mb-4 flex items-center justify-between last:mb-0"><div className="flex items-center gap-3"><div className="flex h-8 w-8 items-center justify-center rounded-sm bg-[#e7f0f4] text-primary"><Plane size={15} /></div><div><div className="amp-mono text-[12px] font-medium">{a.registration}</div><div className="text-[10px] text-muted-foreground">{a.aircraftType} · {number(a.totalCycles)} cycles</div></div></div><div className="text-right"><Status value={a.status} /><div className="amp-mono mt-1 text-[10px] text-muted-foreground">{number(a.totalHours)} FH</div></div></div>)}</div></section>
      <section className="amp-panel rounded-sm xl:col-span-2"><div className="flex items-center justify-between border-b border-border px-5 py-4"><div><div className="amp-eyebrow text-primary">Traceability</div><h2 className="mt-1 text-[15px] font-extrabold">Recent activity</h2></div><span className="amp-mono text-[10px] text-muted-foreground">LAST 8 EVENTS</span></div>{activity.isLoading ? <div className="p-5"><LoadingRows count={3} /></div> : activity.isError ? <div className="p-5"><ErrorState retry={() => activity.refetch()} /></div> : <div className="grid divide-y divide-border/70 md:grid-cols-2 md:divide-x md:divide-y-0">{(activity.data ?? []).slice(0, 6).map((item, index) => <div key={item.id} data-testid={`row-activity-${item.id}`} className={`flex gap-3 px-5 py-4 ${index > 1 ? 'md:border-t md:border-border/70' : ''}`}><div className="mt-0.5 flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-muted text-primary">{item.kind === ActivityKind.record_uploaded ? <UploadCloud size={13} /> : item.kind === ActivityKind.task_updated ? <ClipboardCheck size={13} /> : item.kind === ActivityKind.record_reviewed ? <FileCheck2 size={13} /> : <Plane size={13} />}</div><div className="min-w-0"><div className="text-[12px] font-bold">{item.title}</div><div className="mt-0.5 truncate text-[11px] text-muted-foreground">{item.detail}</div><div className="amp-mono mt-1.5 text-[9px] uppercase text-muted-foreground/70">{relative(item.createdAt)}</div></div></div>)}</div>}</section>
      <section className="amp-panel rounded-sm"><div className="border-b border-border px-5 py-4"><div className="amp-eyebrow text-primary">Record intake</div><h2 className="mt-1 text-[15px] font-extrabold">Review queue</h2></div><div className="p-5"><div className="flex items-end justify-between"><div><div className="amp-mono text-[30px] font-medium tracking-[-.08em]">{number(s?.pendingRecordsCount ?? records.data?.length)}</div><div className="text-[11px] text-muted-foreground">records waiting for disposition</div></div><div className="flex h-11 w-11 items-center justify-center rounded-full border-4 border-amber-100 text-[#9a6700]"><Inbox size={17} /></div></div><Link href="/records" data-testid="link-open-record-queue" className="mt-5 flex items-center justify-between border-t border-border pt-3 text-[11px] font-bold text-primary hover:underline">Open review queue <ChevronRight size={13} /></Link></div></section>
    </div>
  </div>;
}

function Modal({ title, eyebrow, onClose, children }: { title: string; eyebrow: string; onClose: () => void; children: ReactNode }) {
  return <div className="fixed inset-0 z-50 flex items-end justify-center bg-[#10263a]/35 p-0 backdrop-blur-[2px] sm:items-center sm:p-5"><div className="amp-panel max-h-[92dvh] w-full max-w-[620px] overflow-auto rounded-sm bg-card shadow-2xl"><div className="flex items-start justify-between border-b border-border px-5 py-4"><div><div className="amp-eyebrow text-primary">{eyebrow}</div><h2 className="mt-1 text-[17px] font-extrabold tracking-[-.03em]">{title}</h2></div><button onClick={onClose} aria-label="Close dialog" data-testid="button-close-dialog" className="rounded-sm p-1.5 text-muted-foreground hover:bg-muted hover:text-foreground"><X size={17} /></button></div><div className="p-5">{children}</div></div></div>;
}
function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) { return <label className="block"><span className="mb-1.5 block text-[11px] font-bold text-muted-foreground">{label}</span>{children}{hint && <span className="mt-1 block text-[10px] text-muted-foreground">{hint}</span>}</label>; }
const inputClass = 'h-10 w-full rounded-sm border border-input bg-background px-3 text-[12px] outline-none transition-colors placeholder:text-muted-foreground/60 focus:border-primary focus:ring-2 focus:ring-primary/10';
function TaskForm({ aircraft, task, onClose }: { aircraft: Aircraft[]; task?: MaintenanceTask; onClose: () => void }) {
  const qc = useQueryClient(); const create = useCreateMaintenanceTask(); const update = useUpdateMaintenanceTask();
  const [form, setForm] = useState({ aircraftId: String(task?.aircraftId ?? aircraft[0]?.id ?? ''), title: task?.title ?? '', taskNumber: task?.taskNumber ?? '', category: task?.category ?? 'inspection', owner: task?.owner ?? 'Maintenance control', status: task?.status ?? 'on_track', nextDueAt: task?.nextDueAt?.slice(0, 10) ?? '', nextDueHours: String(task?.nextDueHours ?? ''), nextDueCycles: String(task?.nextDueCycles ?? ''), notes: task?.notes ?? '' });
  const set = (key: string, value: string) => setForm((f) => ({ ...f, [key]: value }));
  const submit = (e: FormEvent) => { e.preventDefault(); const payload: any = { title: form.title, taskNumber: form.taskNumber, category: form.category, aircraftId: Number(form.aircraftId), owner: form.owner, notes: form.notes, ...(form.nextDueAt ? { nextDueAt: new Date(form.nextDueAt).toISOString() } : {}), ...(form.nextDueHours ? { nextDueHours: Number(form.nextDueHours) } : {}), ...(form.nextDueCycles ? { nextDueCycles: Number(form.nextDueCycles) } : {}) }; if (task) update.mutate({ taskId: task.id, data: { ...payload, status: form.status } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListMaintenanceTasksQueryKey() }); onClose(); } }); else create.mutate({ data: payload }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListMaintenanceTasksQueryKey() }); onClose(); } }); };
  return <form onSubmit={submit} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><Field label="Aircraft"><select required value={form.aircraftId} onChange={(e) => set('aircraftId', e.target.value)} data-testid="select-task-aircraft" className={inputClass}>{aircraft.map((a) => <option key={a.id} value={a.id}>{a.registration} · {a.aircraftType}</option>)}</select></Field><Field label="Task category"><select value={form.category} onChange={(e) => set('category', e.target.value)} data-testid="select-task-category" className={inputClass}>{Object.values(MaintenanceTaskCategory).map((v) => <option key={v} value={v}>{pretty(v)}</option>)}</select></Field></div><div className="grid gap-4 sm:grid-cols-[1fr_150px]"><Field label="Task title"><input required minLength={2} value={form.title} onChange={(e) => set('title', e.target.value)} data-testid="input-task-title" className={inputClass} placeholder="e.g. Engine oil filter inspection" /></Field><Field label="Task number"><input required value={form.taskNumber} onChange={(e) => set('taskNumber', e.target.value)} data-testid="input-task-number" className={inputClass} placeholder="AMP-52-31" /></Field></div><div className="grid gap-4 sm:grid-cols-3"><Field label="Next due date"><input type="date" value={form.nextDueAt} onChange={(e) => set('nextDueAt', e.target.value)} data-testid="input-task-due-date" className={inputClass} /></Field><Field label="Due at flight hours"><input type="number" min="0" value={form.nextDueHours} onChange={(e) => set('nextDueHours', e.target.value)} data-testid="input-task-due-hours" className={inputClass} placeholder="Optional" /></Field><Field label="Due at cycles"><input type="number" min="0" value={form.nextDueCycles} onChange={(e) => set('nextDueCycles', e.target.value)} data-testid="input-task-due-cycles" className={inputClass} placeholder="Optional" /></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Assigned owner"><input required value={form.owner} onChange={(e) => set('owner', e.target.value)} data-testid="input-task-owner" className={inputClass} /></Field>{task && <Field label="Workflow status"><select value={form.status} onChange={(e) => set('status', e.target.value)} data-testid="select-task-status" className={inputClass}>{Object.values(MaintenanceTaskStatus).map((v) => <option key={v} value={v}>{pretty(v)}</option>)}</select></Field>}</div><Field label="Control notes"><textarea value={form.notes} onChange={(e) => set('notes', e.target.value)} data-testid="textarea-task-notes" className={`${inputClass} h-20 py-2`} placeholder="Add a concise handover note..." /></Field><div className="flex justify-end gap-2 border-t border-border pt-4"><Button variant="secondary" onClick={onClose} testId="button-cancel-task">Cancel</Button><Button type="submit" disabled={create.isPending || update.isPending} testId="button-save-task">{create.isPending || update.isPending ? 'Saving...' : task ? 'Save task update' : 'Add task'}</Button></div></form>;
}

function TasksPage() {
  const [search, setSearch] = useState(''); const [status, setStatus] = useState('all'); const [modal, setModal] = useState<MaintenanceTask | 'new' | null>(null);
  const tasks = useListMaintenanceTasks({ search: search || undefined, status: status === 'all' ? undefined : status as any }); const aircraft = useListAircraft();
  return <div className="amp-fade"><PageIntro eyebrow="Maintenance program / register" title="Task register" description="Search, prioritise, and update every scheduled maintenance and time-change obligation." action={<Button onClick={() => setModal('new')} testId="button-add-task"><Plus size={14} /> Add task</Button>} /><div className="amp-panel mb-4 flex flex-col gap-3 rounded-sm p-3 md:flex-row"><div className="relative min-w-0 flex-1"><Search size={15} className="absolute left-3 top-3 text-muted-foreground" /><input value={search} onChange={(e) => setSearch(e.target.value)} data-testid="input-search-tasks" className={`${inputClass} pl-9`} placeholder="Search task number, aircraft, title or owner" /></div><div className="flex items-center gap-2"><Filter size={14} className="text-muted-foreground" /><select value={status} onChange={(e) => setStatus(e.target.value)} data-testid="select-filter-task-status" className={`${inputClass} w-auto min-w-[150px]`}><option value="all">All statuses</option>{Object.values(MaintenanceTaskStatus).map((v) => <option key={v} value={v}>{pretty(v)}</option>)}</select></div><div className="hidden items-center gap-2 px-2 text-[10px] text-muted-foreground lg:flex"><SlidersHorizontal size={13} /> {tasks.data?.length ?? 0} matching</div></div>{tasks.isLoading ? <LoadingRows count={6} /> : tasks.isError ? <ErrorState retry={() => tasks.refetch()} /> : !tasks.data?.length ? <EmptyState icon={ClipboardCheck} title="No tasks match this view" detail="Try a broader search or add the next maintenance obligation to the register." action={<Button onClick={() => setModal('new')} testId="button-empty-add-task"><Plus size={13} /> Add first task</Button>} /> : <div className="amp-panel overflow-hidden rounded-sm"><div className="hidden overflow-x-auto md:block"><table className="w-full text-left"><thead className="bg-muted/70"><tr className="amp-eyebrow text-muted-foreground"><th className="px-5 py-3">Task / aircraft</th><th className="px-4 py-3">Category</th><th className="px-4 py-3">Due horizon</th><th className="px-4 py-3">Owner</th><th className="px-4 py-3">Status</th><th className="px-5 py-3 text-right">Action</th></tr></thead><tbody className="divide-y divide-border/70">{tasks.data.map((t) => <tr key={t.id} data-testid={`row-task-${t.id}`} className="group transition-colors hover:bg-muted/40"><td className="px-5 py-4"><div className="amp-mono text-[11px] text-muted-foreground">{t.taskNumber}</div><div className="mt-1 text-[12px] font-bold">{t.title}</div><div className="mt-1 text-[10px] font-semibold text-primary">{t.aircraftRegistration}</div></td><td className="px-4 py-4 text-[11px] text-muted-foreground">{pretty(t.category)}</td><td className="px-4 py-4"><div className={`amp-mono text-[11px] font-medium ${t.status === 'overdue' ? 'text-[#ad3933]' : 'text-foreground'}`}>{t.status === 'overdue' ? 'Past due' : date(t.nextDueAt)}</div><div className="mt-1 text-[10px] text-muted-foreground">{t.nextDueHours ? `${number(t.nextDueHours)} FH` : t.nextDueCycles ? `${number(t.nextDueCycles)} FC` : 'Date controlled'}</div></td><td className="px-4 py-4 text-[11px] text-muted-foreground">{t.owner}</td><td className="px-4 py-4"><Status value={t.status} /></td><td className="px-5 py-4 text-right"><Button variant="quiet" onClick={() => setModal(t)} testId={`button-edit-task-${t.id}`}><MoreHorizontal size={15} /></Button></td></tr>)}</tbody></table></div><div className="divide-y divide-border/70 md:hidden">{tasks.data.map((t) => <button key={t.id} onClick={() => setModal(t)} data-testid={`card-task-${t.id}`} className="block w-full p-4 text-left hover:bg-muted/50"><div className="flex justify-between"><span className="amp-mono text-[10px] text-muted-foreground">{t.taskNumber}</span><Status value={t.status} /></div><div className="mt-2 text-[12px] font-bold">{t.title}</div><div className="mt-1 text-[11px] text-primary">{t.aircraftRegistration} · {date(t.nextDueAt)}</div></button>)}</div></div>}{modal && <Modal eyebrow={modal === 'new' ? 'Register obligation' : 'Update control item'} title={modal === 'new' ? 'Add maintenance task' : 'Update task status'} onClose={() => setModal(null)}><TaskForm aircraft={aircraft.data ?? []} task={modal === 'new' ? undefined : modal} onClose={() => setModal(null)} /></Modal>}</div>;
}

function AircraftForm({ aircraft, onClose }: { aircraft?: Aircraft; onClose: () => void }) {
  const qc = useQueryClient(); const create = useCreateAircraft(); const update = useUpdateAircraft();
  const [form, setForm] = useState({ registration: aircraft?.registration ?? '', aircraftType: aircraft?.aircraftType ?? '', serialNumber: aircraft?.serialNumber ?? '', operator: aircraft?.operator ?? 'Northstar Airways', totalHours: String(aircraft?.totalHours ?? ''), totalCycles: String(aircraft?.totalCycles ?? ''), status: aircraft?.status ?? 'serviceable' });
  const set = (k: string, v: string) => setForm((f) => ({ ...f, [k]: v }));
  const submit = (e: FormEvent) => { e.preventDefault(); if (aircraft) update.mutate({ aircraftId: aircraft.id, data: { totalHours: Number(form.totalHours), totalCycles: Number(form.totalCycles), status: form.status as any } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListAircraftQueryKey() }); qc.invalidateQueries({ queryKey: getGetAircraftQueryKey(aircraft.id) }); onClose(); } }); else create.mutate({ data: { registration: form.registration, aircraftType: form.aircraftType, serialNumber: form.serialNumber, operator: form.operator, totalHours: Number(form.totalHours || 0), totalCycles: Number(form.totalCycles || 0) } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListAircraftQueryKey() }); onClose(); } }); };
  return <form onSubmit={submit} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><Field label="Registration"><input required disabled={!!aircraft} value={form.registration} onChange={(e) => set('registration', e.target.value.toUpperCase())} data-testid="input-aircraft-registration" className={inputClass} placeholder="N8-AMP" /></Field><Field label="Aircraft type"><input required disabled={!!aircraft} value={form.aircraftType} onChange={(e) => set('aircraftType', e.target.value)} data-testid="input-aircraft-type" className={inputClass} placeholder="A320-214" /></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Serial number"><input required disabled={!!aircraft} value={form.serialNumber} onChange={(e) => set('serialNumber', e.target.value)} data-testid="input-aircraft-serial" className={inputClass} placeholder="MSN 4812" /></Field><Field label="Operator"><input required disabled={!!aircraft} value={form.operator} onChange={(e) => set('operator', e.target.value)} data-testid="input-aircraft-operator" className={inputClass} /></Field></div><div className="grid gap-4 sm:grid-cols-3"><Field label="Total flight hours"><input required type="number" min="0" value={form.totalHours} onChange={(e) => set('totalHours', e.target.value)} data-testid="input-aircraft-hours" className={inputClass} /></Field><Field label="Total cycles"><input required type="number" min="0" value={form.totalCycles} onChange={(e) => set('totalCycles', e.target.value)} data-testid="input-aircraft-cycles" className={inputClass} /></Field>{aircraft && <Field label="Service status"><select value={form.status} onChange={(e) => set('status', e.target.value)} data-testid="select-aircraft-status" className={inputClass}>{Object.values(AircraftStatus).map((v) => <option key={v} value={v}>{pretty(v)}</option>)}</select></Field>}</div><div className="flex justify-end gap-2 border-t border-border pt-4"><Button variant="secondary" onClick={onClose} testId="button-cancel-aircraft">Cancel</Button><Button type="submit" disabled={create.isPending || update.isPending} testId="button-save-aircraft">{create.isPending || update.isPending ? 'Saving...' : aircraft ? 'Save utilisation' : 'Add aircraft'}</Button></div></form>;
}

function AircraftPage() {
  const [search, setSearch] = useState(''); const [modal, setModal] = useState<Aircraft | 'new' | null>(null); const aircraft = useListAircraft(); const selected = modal && modal !== 'new' ? modal : null; const detail = useGetAircraft(selected?.id ?? 0, { query: { enabled: !!selected, queryKey: getGetAircraftQueryKey(selected?.id ?? 0) } });
  const filtered = (aircraft.data ?? []).filter((a) => `${a.registration} ${a.aircraftType} ${a.serialNumber}`.toLowerCase().includes(search.toLowerCase()));
  return <div className="amp-fade"><PageIntro eyebrow="Asset control / fleet" title="Aircraft fleet" description="A single operational view of the aircraft under the programme, their utilisation, and current service status." action={<Button onClick={() => setModal('new')} testId="button-add-aircraft"><Plus size={14} /> Add aircraft</Button>} /><div className="mb-4 flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search size={15} className="absolute left-3 top-3 text-muted-foreground" /><input value={search} onChange={(e) => setSearch(e.target.value)} data-testid="input-search-aircraft" className={`${inputClass} pl-9`} placeholder="Search registration, type or serial number" /></div><div className="amp-mono flex items-center justify-end px-1 text-[10px] text-muted-foreground">{filtered.length} / {aircraft.data?.length ?? 0} aircraft</div></div>{aircraft.isLoading ? <LoadingRows count={5} /> : aircraft.isError ? <ErrorState retry={() => aircraft.refetch()} /> : !filtered.length ? <EmptyState icon={Plane} title="No aircraft in this view" detail="Add an aircraft to start tracking programme coverage and utilisation." action={<Button onClick={() => setModal('new')} testId="button-empty-add-aircraft"><Plus size={13} /> Add aircraft</Button>} /> : <div className="grid gap-3 xl:grid-cols-2">{filtered.map((a, i) => <div key={a.id} data-testid={`card-aircraft-${a.id}`} className={`amp-panel amp-rise amp-delay-${Math.min(i + 1, 3)} rounded-sm p-5 transition-all hover:-translate-y-0.5 hover:shadow-md`}><div className="flex items-start justify-between"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-sm bg-[#e7f0f4] text-primary"><Plane size={19} /></div><div><div className="amp-mono text-[15px] font-medium">{a.registration}</div><div className="mt-0.5 text-[11px] text-muted-foreground">{a.aircraftType} · {a.serialNumber}</div></div></div><Status value={a.status} /></div><div className="my-5 grid grid-cols-3 border-y border-border/70 py-3"><div><div className="amp-eyebrow text-muted-foreground">Flight hours</div><div className="amp-mono mt-1 text-[16px]">{number(a.totalHours)}</div></div><div><div className="amp-eyebrow text-muted-foreground">Cycles</div><div className="amp-mono mt-1 text-[16px]">{number(a.totalCycles)}</div></div><div><div className="amp-eyebrow text-muted-foreground">Operator</div><div className="mt-1 truncate text-[11px] font-semibold">{a.operator}</div></div></div><div className="flex items-center justify-between"><span className="text-[10px] text-muted-foreground">Updated {date(a.updatedAt)}</span><Button variant="quiet" onClick={() => setModal(a)} testId={`button-edit-aircraft-${a.id}`}>Update utilisation <ArrowUpRight size={13} /></Button></div></div>)}</div>}{modal && <Modal eyebrow={modal === 'new' ? 'Fleet onboarding' : `${selected?.registration} / utilisation`} title={modal === 'new' ? 'Add aircraft' : 'Update aircraft'} onClose={() => setModal(null)}>{selected && detail.isLoading ? <LoadingRows count={3} /> : <AircraftForm aircraft={modal === 'new' ? undefined : (detail.data ?? selected ?? undefined)} onClose={() => setModal(null)} />}</Modal>}</div>;
}

function RecordsPage() {
  const [search, setSearch] = useState(''); const [review, setReview] = useState('all'); const [modal, setModal] = useState(false); const [selected, setSelected] = useState<MaintenanceRecord | null>(null);
  const records = useListMaintenanceRecords({ search: search || undefined, reviewStatus: review === 'all' ? undefined : review as any }); const aircraft = useListAircraft(); const qc = useQueryClient(); const reviewMutation = useReviewMaintenanceRecord(); const create = useCreateMaintenanceRecord(); const upload = useRequestUploadUrl();
  const [form, setForm] = useState({ aircraftId: '', documentName: '', recordType: 'tech_log', airline: 'Northstar Airways', description: '' }); const [file, setFile] = useState<File | null>(null);
  const submit = (e: FormEvent) => { e.preventDefault(); if (!file) return; upload.mutate({ data: { name: file.name, size: file.size, contentType: file.type || 'application/octet-stream' } }, { onSuccess: (response) => { create.mutate({ data: { aircraftId: Number(form.aircraftId), documentName: form.documentName || file.name, recordType: form.recordType as any, airline: form.airline, objectPath: response.objectPath, fileSize: file.size, description: form.description } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListMaintenanceRecordsQueryKey() }); setModal(false); setFile(null); } }); } }); };
  const decide = (record: MaintenanceRecord, value: 'reviewed' | 'rejected') => reviewMutation.mutate({ recordId: record.id, data: { reviewStatus: value as RecordReviewInputReviewStatus } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListMaintenanceRecordsQueryKey() }); qc.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() }); setSelected(null); } });
  return <div className="amp-fade"><PageIntro eyebrow="Document control / intake" title="Maintenance records" description="Receive, classify, and disposition airline records before they enter the controlled programme evidence trail." action={<Button onClick={() => setModal(true)} testId="button-upload-record"><UploadCloud size={14} /> Upload record</Button>} /><div className="amp-panel mb-4 flex flex-col gap-3 rounded-sm p-3 md:flex-row"><div className="relative min-w-0 flex-1"><Search size={15} className="absolute left-3 top-3 text-muted-foreground" /><input value={search} onChange={(e) => setSearch(e.target.value)} data-testid="input-search-records" className={`${inputClass} pl-9`} placeholder="Search document, airline or aircraft" /></div><select value={review} onChange={(e) => setReview(e.target.value)} data-testid="select-filter-record-status" className={`${inputClass} w-auto min-w-[145px]`}><option value="all">All review states</option>{Object.values(MaintenanceRecordReviewStatus).map((v) => <option key={v} value={v}>{pretty(v)}</option>)}</select></div>{records.isLoading ? <LoadingRows count={5} /> : records.isError ? <ErrorState retry={() => records.refetch()} /> : !records.data?.length ? <EmptyState icon={FileText} title="No records in this queue" detail="Uploaded documents will appear here with their review state and evidence metadata." action={<Button onClick={() => setModal(true)} testId="button-empty-upload-record"><UploadCloud size={13} /> Upload record</Button>} /> : <div className="amp-panel overflow-hidden rounded-sm"><div className="divide-y divide-border/70">{records.data.map((r) => <div key={r.id} data-testid={`row-record-${r.id}`} className="group flex flex-col gap-4 px-5 py-4 transition-colors hover:bg-muted/40 md:flex-row md:items-center"><div className="flex min-w-0 flex-1 items-center gap-3"><div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-sm bg-muted text-primary"><FileText size={16} /></div><div className="min-w-0"><div className="truncate text-[12px] font-bold">{r.documentName}</div><div className="mt-1 flex flex-wrap gap-2 text-[10px] text-muted-foreground"><span className="amp-mono text-primary">{r.aircraftRegistration}</span><span>{pretty(r.recordType)}</span><span>{number(r.fileSize / 1024)} KB</span><span>{date(r.uploadedAt)}</span></div></div></div><div className="flex items-center justify-between gap-3 md:justify-end"><Status value={r.reviewStatus} /><Button variant="quiet" onClick={() => setSelected(r)} testId={`button-review-record-${r.id}`}>Review <ChevronRight size={13} /></Button></div></div>)}</div></div>}{selected && <Modal eyebrow="Evidence disposition" title={selected.documentName} onClose={() => setSelected(null)}><div className="rounded-sm border border-border bg-muted/40 p-4"><div className="grid grid-cols-2 gap-4"><div><div className="amp-eyebrow text-muted-foreground">Aircraft</div><div className="amp-mono mt-1 text-[12px]">{selected.aircraftRegistration}</div></div><div><div className="amp-eyebrow text-muted-foreground">Record type</div><div className="mt-1 text-[12px] font-semibold">{pretty(selected.recordType)}</div></div><div><div className="amp-eyebrow text-muted-foreground">Uploaded by</div><div className="mt-1 text-[12px]">{selected.uploadedBy}</div></div><div><div className="amp-eyebrow text-muted-foreground">Uploaded</div><div className="mt-1 text-[12px]">{date(selected.uploadedAt)}</div></div></div>{selected.description && <p className="mt-4 border-t border-border pt-3 text-[11px] leading-relaxed text-muted-foreground">{selected.description}</p>}</div><div className="mt-5 flex justify-end gap-2"><Button variant="danger" onClick={() => decide(selected, 'rejected')} disabled={reviewMutation.isPending} testId={`button-reject-record-${selected.id}`}><XCircle size={14} /> Reject record</Button><Button onClick={() => decide(selected, 'reviewed')} disabled={reviewMutation.isPending} testId={`button-approve-record-${selected.id}`}><Check size={14} /> Mark reviewed</Button></div></Modal>}{modal && <Modal eyebrow="Evidence intake" title="Upload maintenance record" onClose={() => setModal(false)}><form onSubmit={submit} className="space-y-4"><Field label="File" hint="PDF, JPG or PNG · metadata is retained with the record"><input required type="file" accept=".pdf,.jpg,.jpeg,.png" onChange={(e) => setFile(e.target.files?.[0] ?? null)} data-testid="input-record-file" className={`${inputClass} py-2`} /></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Aircraft"><select required value={form.aircraftId} onChange={(e) => setForm({ ...form, aircraftId: e.target.value })} data-testid="select-record-aircraft" className={inputClass}><option value="">Select aircraft</option>{(aircraft.data ?? []).map((a) => <option key={a.id} value={a.id}>{a.registration}</option>)}</select></Field><Field label="Record type"><select value={form.recordType} onChange={(e) => setForm({ ...form, recordType: e.target.value })} data-testid="select-record-type" className={inputClass}>{Object.values(MaintenanceRecordRecordType).map((v) => <option key={v} value={v}>{pretty(v)}</option>)}</select></Field></div><Field label="Document name"><input value={form.documentName} onChange={(e) => setForm({ ...form, documentName: e.target.value })} data-testid="input-record-name" className={inputClass} placeholder="Defaults to file name" /></Field><Field label="Description"><textarea value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} data-testid="textarea-record-description" className={`${inputClass} h-20 py-2`} placeholder="What should the reviewer verify?" /></Field><div className="flex justify-end gap-2 border-t border-border pt-4"><Button variant="secondary" onClick={() => setModal(false)} testId="button-cancel-record">Cancel</Button><Button type="submit" disabled={!file || upload.isPending || create.isPending} testId="button-save-record">{upload.isPending || create.isPending ? 'Uploading...' : 'Upload for review'}</Button></div></form></Modal>}</div>;
}

function SettingsPage() {
  const [saved, setSaved] = useState(false); const [compact, setCompact] = useState(true); const [digest, setDigest] = useState(true); const [window, setWindow] = useState('30');
  const save = () => { setSaved(true); setTimeout(() => setSaved(false), 2400); };
  return <div className="amp-fade"><PageIntro eyebrow="Workspace / configuration" title="Settings" description="Tune the control surface for your team without changing the underlying approved maintenance programme." action={<Button onClick={save} testId="button-save-settings">{saved ? <><CheckCircle2 size={14} /> Preferences saved</> : 'Save preferences'}</Button>} /><div className="grid gap-5 xl:grid-cols-[1fr_320px]"><div className="space-y-5"><section className="amp-panel rounded-sm"><div className="border-b border-border px-5 py-4"><div className="amp-eyebrow text-primary">Workspace identity</div><h2 className="mt-1 text-[15px] font-extrabold">Operational profile</h2></div><div className="grid gap-4 p-5 sm:grid-cols-2"><Field label="Workspace name"><input defaultValue="Northstar Airways" data-testid="input-workspace-name" className={inputClass} /></Field><Field label="Primary timezone"><select defaultValue="UTC" data-testid="select-workspace-timezone" className={inputClass}><option>UTC</option><option>Europe/London</option><option>America/New_York</option></select></Field><Field label="Control centre identifier"><input defaultValue="NS-MCC-01" data-testid="input-control-identifier" className={inputClass} /></Field><Field label="Date format"><select defaultValue="DD MMM YYYY" data-testid="select-date-format" className={inputClass}><option>DD MMM YYYY</option><option>YYYY-MM-DD</option></select></Field></div></section><section className="amp-panel rounded-sm"><div className="border-b border-border px-5 py-4"><div className="amp-eyebrow text-primary">Control surface</div><h2 className="mt-1 text-[15px] font-extrabold">Display preferences</h2></div><div className="divide-y divide-border/70"><label className="flex items-center justify-between gap-4 px-5 py-4"><div><div className="text-[12px] font-bold">Dense register rows</div><div className="mt-1 text-[11px] text-muted-foreground">Keep more task and record lines in the first viewport.</div></div><input type="checkbox" checked={compact} onChange={(e) => setCompact(e.target.checked)} data-testid="toggle-compact-rows" className="h-4 w-4 accent-primary" /></label><label className="flex items-center justify-between gap-4 px-5 py-4"><div><div className="text-[12px] font-bold">Daily control digest</div><div className="mt-1 text-[11px] text-muted-foreground">Summarise overdue items and pending records at shift handover.</div></div><input type="checkbox" checked={digest} onChange={(e) => setDigest(e.target.checked)} data-testid="toggle-daily-digest" className="h-4 w-4 accent-primary" /></label><div className="flex items-center justify-between gap-4 px-5 py-4"><div><div className="text-[12px] font-bold">Due-soon horizon</div><div className="mt-1 text-[11px] text-muted-foreground">Used for dashboard urgency and queue emphasis.</div></div><select value={window} onChange={(e) => setWindow(e.target.value)} data-testid="select-due-horizon" className={`${inputClass} w-auto`}><option value="14">14 days</option><option value="30">30 days</option><option value="45">45 days</option></select></div></div></section></div><aside className="space-y-5"><section className="amp-panel rounded-sm p-5"><div className="mb-4 flex h-10 w-10 items-center justify-center rounded-sm bg-[#e7f0f4] text-primary"><Users size={18} /></div><div className="amp-eyebrow text-primary">Access</div><h2 className="mt-1 text-[15px] font-extrabold">Control team access</h2><p className="mt-2 text-[11px] leading-relaxed text-muted-foreground">Manage who can update utilisation, change task status, and disposition evidence.</p><Button variant="secondary" onClick={() => setSaved(true)} testId="button-manage-access" >Manage access <ArrowUpRight size={13} /></Button></section><section className="amp-panel amp-grid rounded-sm p-5"><div className="amp-eyebrow text-primary">System posture</div><div className="mt-4 space-y-3"><div className="flex justify-between text-[11px]"><span className="text-muted-foreground">API connection</span><span className="flex items-center gap-1.5 font-bold text-[#2c7853]"><span className="h-1.5 w-1.5 rounded-full bg-[#3c9d6c]" /> Healthy</span></div><div className="flex justify-between text-[11px]"><span className="text-muted-foreground">Last sync</span><span className="amp-mono">12:42 UTC</span></div><div className="flex justify-between text-[11px]"><span className="text-muted-foreground">Programme revision</span><span className="amp-mono">AMP-24.06</span></div></div></section></aside></div></div>;
}

function Router() { return <ErrorBoundary><AppShell><Switch><Route path="/" component={Dashboard} /><Route path="/tasks" component={TasksPage} /><Route path="/aircraft" component={AircraftPage} /><Route path="/records" component={RecordsPage} /><Route path="/settings" component={SettingsPage} /><Route component={NotFound} /></Switch></AppShell></ErrorBoundary>; }
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;